-- Shortest Path in a Maze (Medium)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$shortest-path-in-a-maze$q$, $q$Shortest Path in a Maze$q$, $q$A maze is a grid where . is an open cell and # is a wall. You start in the top-left cell and want to reach the bottom-right cell. In one step you move to an open cell above, below, left or right.

Print the smallest number of steps, or -1 if the exit cannot be reached. If the start or the exit is a wall, the answer is -1. If the grid has one open cell, the answer is 0.$q$, $q$Medium$q$, $q$Graphs$q$, 'code', ARRAY[$q$graph$q$, $q$bfs$q$, $q$grid$q$, $q$shortest-path$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: R and C.\n    # Next R lines: C characters each, . or #.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: R and C.\n// Next R lines: C characters each, . or #.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: R and C.\n        // Next R lines: C characters each, . or #.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: R and C.\n    // Next R lines: C characters each, . or #.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: R and C.\n    // Next R lines: C characters each, . or #.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "3 3\n...\n.#.\n...", "output": "4", "explanation": "Go around the wall: 4 steps."}, {"input": "2 2\n.#\n#.", "output": "-1", "explanation": "Both routes are blocked."}]$q$::jsonb, ARRAY[$q$1 ≤ R, C ≤ 200$q$]::text[], 25, 1014, 2000, 262144, $q$Line 1: R and C.
Next R lines: C characters each, . or #.$q$, $q$One integer: the minimum steps, or -1.$q$, $q$Every move costs 1, so breadth-first search from the start finds the shortest path. Keep a distance grid initialised to -1, push the start with distance 0, and expand neighbours that are open and unvisited. Check the start and exit cells first. O(R·C).$q$, false)
ON CONFLICT (slug) DO NOTHING;

